package tw.rex.learningtv;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;
/** Durable, untruncated history shared by practice and watch mode. */
final class LearningHistory extends SQLiteOpenHelper {
 LearningHistory(Context c){super(c,"learning-history.db",null,1);migrate(c.getSharedPreferences("learning",0).getString("history","[]"));}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE attempts (id TEXT PRIMARY KEY,time INTEGER NOT NULL,body TEXT NOT NULL)");db.execSQL("CREATE INDEX by_time ON attempts(time)");db.execSQL("CREATE TABLE metadata (key TEXT PRIMARY KEY)");}
 public void onUpgrade(SQLiteDatabase db,int old,int next){}
 void migrate(String legacy){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{try(Cursor c=db.rawQuery("SELECT key FROM metadata WHERE key='legacy-v1'",null)){if(c.moveToFirst())return;}JSONArray a=new JSONArray(legacy);for(int i=0;i<a.length();i++){JSONObject q=a.optJSONObject(i);if(q!=null)insert(db,"legacy-"+i,q);}db.execSQL("INSERT INTO metadata(key) VALUES('legacy-v1')");db.setTransactionSuccessful();}catch(JSONException e){android.util.Log.e("LearningHistory","Legacy history unreadable; retained for retry",e);}finally{db.endTransaction();}}
 void insert(SQLiteDatabase db,String id,JSONObject q){ContentValues v=new ContentValues();v.put("id",id);v.put("time",q.optLong("time"));v.put("body",q.toString());if(db.insertWithOnConflict("attempts",null,v,SQLiteDatabase.CONFLICT_IGNORE)<0)throw new SQLiteException("無法儲存作答紀錄");}
 void append(JSONObject q){insert(getWritableDatabase(),java.util.UUID.randomUUID().toString(),q);}
 JSONArray between(long from,long until){JSONArray a=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT body FROM attempts WHERE time>=? AND time<? ORDER BY time DESC,rowid DESC",new String[]{""+from,""+until})){while(c.moveToNext())try{a.put(new JSONObject(c.getString(0)));}catch(JSONException ignored){}}return a;}
 java.util.Map<Integer,Integer> monthCounts(java.util.Calendar month){java.util.Calendar start=(java.util.Calendar)month.clone();start.set(java.util.Calendar.DAY_OF_MONTH,1);start.set(java.util.Calendar.HOUR_OF_DAY,0);start.set(java.util.Calendar.MINUTE,0);start.set(java.util.Calendar.SECOND,0);start.set(java.util.Calendar.MILLISECOND,0);java.util.Calendar end=(java.util.Calendar)start.clone();end.add(java.util.Calendar.MONTH,1);java.util.Map<Integer,Integer> counts=new java.util.HashMap<Integer,Integer>();try(Cursor c=getReadableDatabase().rawQuery("SELECT time FROM attempts WHERE time>=? AND time<?",new String[]{""+start.getTimeInMillis(),""+end.getTimeInMillis()})){while(c.moveToNext()){java.util.Calendar d=java.util.Calendar.getInstance();d.setTimeInMillis(c.getLong(0));int day=d.get(java.util.Calendar.DAY_OF_MONTH);counts.put(day,counts.containsKey(day)?counts.get(day)+1:1);}}return counts;}
}
